//! Prost bindings for the celestia-app v10 state-machine protobuf schema.
//!
//! Generated by `cargo xtask gen-proto` from sources vendored under
//! `proto/` at the exact versions celestia-app v10.4.0 pins:
//!
//! | Source | Version |
//! |---|---|
//! | `celestiaorg/cosmos-sdk` | v0.52.12 |
//! | `celestiaorg/ibc-go/v8` | v8.7.2 |
//! | `celestiaorg/celestia-app/v10` | v10.4.0 |
//! | `celestiaorg/hyperlane-cosmos` | v1.3.0 |
//! | `cosmos/ibc-apps/.../packet-forward-middleware/v8` | v8.2.0 |
//!
//! `tendermint.*` resolves to [`celestia_core_proto`] and
//! `cosmos.ics23.v1.*` to the `ics23` crate. Do not edit `src/gen/`.

#![allow(missing_docs, clippy::all, clippy::pedantic, rustdoc::all)]

include!("gen/mod.rs");

pub mod any;
pub mod getsigners_schema;
pub mod registry;
pub mod services;
pub mod signers;
pub mod wire_table;

pub use any::Any;
pub use celestia_core_proto;

#[cfg(test)]
mod tests {
    use prost::Message;

    #[test]
    fn celestia_and_cosmos_types_link() {
        let p = super::celestia::blob::v1::Params {
            gas_per_blob_byte: 8,
            gov_max_square_size: 128,
        };
        let b = p.encode_to_vec();
        assert_eq!(
            super::celestia::blob::v1::Params::decode(b.as_slice()).unwrap(),
            p
        );
        let _ = super::cosmos::bank::v1beta1::MsgSend::default();
        let _ = super::hyperlane::warp::v1::HypToken::default();
        let _ = super::ibc::core::client::v1::Params::default();
    }

    /// gogoproto keeps invalid UTF-8 in string fields (any bytes); the Go
    /// form (`gostr`) round-trips them byte-for-byte, including repeated
    /// strings, maps, oneofs and a valid char of the reserved set.
    #[test]
    fn strings_carry_any_bytes() {
        use super::cosmos::staking::v1beta1::{Description, MsgEditValidator};
        let desc: &[u8] = b"\x0a\x03a\xffb\x12\x04\xf4\x8f\xbf\xbf\x1a\x02\xe2\x82";
        let d = Description::decode(desc).unwrap_or_default();
        assert_eq!(gostr::to_go_bytes(&d.moniker).as_ref(), b"a\xffb");
        assert_eq!(gostr::go_len(&d.moniker), 3);
        assert_eq!(d.identity.chars().count(), 4);
        assert_eq!(d.encode_to_vec(), desc);
        let m = MsgEditValidator {
            description: Some(d),
            validator_address: "x".into(),
            ..Default::default()
        };
        let wire = m.encode_to_vec();
        assert_eq!(m.encoded_len(), wire.len());
        assert_eq!(MsgEditValidator::decode(wire.as_slice()).ok(), Some(m));
        // repeated strings and map<string, string>
        let s = super::cosmos::authz::v1beta1::GenericAuthorization {
            msg: gostr::from_go_bytes(b"/\x80").into_owned(),
        };
        assert_eq!(s.encode_to_vec(), b"\x0a\x02/\x80");
        let st = super::cosmos::feegrant::v1beta1::AllowedMsgAllowance {
            allowance: None,
            allowed_messages: vec![gostr::from_go_bytes(b"\xc3").into_owned()],
        };
        let w = st.encode_to_vec();
        assert_eq!(w, b"\x12\x01\xc3");
        assert_eq!(
            super::cosmos::feegrant::v1beta1::AllowedMsgAllowance::decode(w.as_slice()).ok(),
            Some(st)
        );
    }

    #[test]
    fn any_jsonpb_roundtrip() {
        use super::cosmos::bank::v1beta1::MsgSend;
        use super::cosmos::base::v1beta1::Coin;
        let msg = MsgSend {
            from_address: "celestia1a".into(),
            to_address: "celestia1b".into(),
            amount: vec![Coin {
                denom: "utia".into(),
                amount: "5".into(),
            }],
        };
        let any = super::Any::pack(&msg);
        assert_eq!(any.type_url, "/cosmos.bank.v1beta1.MsgSend");
        let json = serde_json::to_value(&any).unwrap();
        assert_eq!(json["@type"], "/cosmos.bank.v1beta1.MsgSend");
        assert_eq!(json["from_address"], "celestia1a");
        let back: super::Any = serde_json::from_value(json).unwrap();
        assert_eq!(back, any);
        assert_eq!(back.unpack::<MsgSend>().unwrap().unwrap(), msg);
    }
}
